  static void Grass(Transform parent){for(int batch=0;batch<9;batch++){var v=new List<Vector3>();var t=new List<int>();var colors=new List<Color>();for(int tuft=0;tuft<2200;tuft++){float x=R(-56,57),z=R(-18,108);if(Mathf.PerlinNoise(x*.19f+73,z*.18f+51)<.35f||z>70&&R(0,1)<.5f)continue;if(Mathf.Pow((x-13)/10.4f,2)+Mathf.Pow((z-19)/10.4f,2)<1)continue;float path=-5+5*Mathf.Sin(z*.055f);if(Mathf.Abs(x-path)<1.5f&&R(0,1)<.8f)continue;float size=R(.16f,.47f);for(int b=0;b<random.Next(3,7);b++){float xx=x+R(-.2f,.2f),zz=z+R(-.2f,.2f),a=R(0,6.28f),w=R(.025f,.065f);var p=V(xx,Ground(xx,zz)+.012f,zz);var side=V(Mathf.Cos(a)*w,0,Mathf.Sin(a)*w);Tri(v,t,p-side,p+side,p+V(R(-.15f,.15f),size*R(.7f,1.3f),R(-.15f,.15f)),Vector3.up);var color=Color.Lerp(MeadowColor(xx,zz),C("#CBD080").linear,R(0,.3f));while(colors.Count<v.Count)colors.Add(color);}}var mesh=SaveMesh("Grass_Tufts_"+batch,v,t);mesh.SetColors(colors);var ns=new Vector3[v.Count];for(int i=0;i<ns.Length;i++)ns[i]=Vector3.up;mesh.normals=ns;EditorUtility.SetDirty(mesh);Shape("Clustered meadow grass "+batch,mesh,Vector3.zero,Vector3.one,meadow,parent);}
